/* OSHE brand standard for generated PDFs: colours, Manrope + Figtree fonts, header band and status labels.
   Needs the @pdf-lib/fontkit package (npm install @pdf-lib/fontkit). */

export const BRAND = {
  deep: "#0F3329", heading: "#1A5A48", teal: "#0AADA1", body: "#22302C", muted: "#5A6B66", grey: "#A9BDCA",
  status: {
    overdue: { line: "#9B1C1C", fill: "#D7A4A4", label: "Overdue" },
    action: { line: "#C2410C", fill: "#E7B39E", label: "Action required" },
    scheduled: { line: "#0AADA1", fill: "#84D6D0", label: "Scheduled" },
    completed: { line: "#1F6B55", fill: "#8FB5AA", label: "Completed" },
    pending: { line: "#A9BDCA", fill: "#DDE6EC", label: "Pending" },
  },
};

export function hexColor(rgb, hex) {
  const n = parseInt(hex.slice(1), 16);
  return rgb(((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255);
}

const FONT_DATA = {"title": "", "head": "", "body": "", "label": ""};

function bytesOf(b64) {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

// Manrope for titles and headings, Figtree for body and labels. Falls back to Helvetica if the
// fonts can't be loaded so a PDF is still produced.
export async function embedBrandFonts(pdfDoc, StandardFonts) {
  try {
    const mod = await import("@pdf-lib/fontkit");
    pdfDoc.registerFontkit(mod.default || mod);
    return {
      title: await pdfDoc.embedFont(bytesOf(FONT_DATA.title), { subset: true }),
      head: await pdfDoc.embedFont(bytesOf(FONT_DATA.head), { subset: true }),
      body: await pdfDoc.embedFont(bytesOf(FONT_DATA.body), { subset: true }),
      label: await pdfDoc.embedFont(bytesOf(FONT_DATA.label), { subset: true }),
    };
  } catch (err) {
    console.error("Brand fonts failed, using Helvetica:", err);
    const regular = await pdfDoc.embedFont(StandardFonts.Helvetica);
    const bold = await pdfDoc.embedFont(StandardFonts.HelveticaBold);
    return { title: bold, head: bold, body: regular, label: bold };
  }
}

// Deep green band with a teal rule under it. OSHE logo and the white title and client name on
// the left, the client logo top right.
export function drawBrandBand({ page, rgb, fonts, W, H, bandH, M, title, clientName, osheLogo, clientLogo, centerTitle }) {
  const deep = hexColor(rgb, BRAND.deep), teal = hexColor(rgb, BRAND.teal), white = rgb(1, 1, 1);
  page.drawRectangle({ x: 0, y: H - bandH, width: W, height: bandH, color: deep });
  page.drawRectangle({ x: 0, y: H - bandH - 3, width: W, height: 3, color: teal });
  let textX = M;
  let rightEdge = W - M;
  if (clientLogo) {
    const sc = Math.min((bandH - 40) / clientLogo.height, 120 / clientLogo.width);
    const w = clientLogo.width * sc, h = clientLogo.height * sc;
    page.drawImage(clientLogo, { x: W - M - w, y: H - bandH + (bandH - h) / 2, width: w, height: h });
    rightEdge = W - M - w - 16;
  }
  if (osheLogo) {
    const sc = Math.min(30 / osheLogo.height, 110 / osheLogo.width);
    const w = osheLogo.width * sc, h = osheLogo.height * sc;
    page.drawImage(osheLogo, { x: M, y: H - bandH + (bandH - h) / 2, width: w, height: h });
    textX = M + w + 20;
  }
  const fit = (text, font, size, maxW) => {
    let t = text;
    while (t.length > 4 && font.widthOfTextAtSize(t, size) > maxW) t = t.slice(0, -1);
    return t === text ? t : t.slice(0, -1) + "...";
  };
  const place = (text, font, size, yy) => {
    const t = fit(text, font, size, rightEdge - textX);
    const x = centerTitle ? Math.max(textX, (W - font.widthOfTextAtSize(t, size)) / 2) : textX;
    page.drawText(t, { x, y: yy, size, font, color: white });
  };
  place(title, fonts.title, 17, H - bandH / 2 + 3);
  if (clientName) place(clientName, fonts.label, 10.5, H - bandH / 2 - 15);
}

export function statusWidth(fonts, size) {
  return fonts.label.widthOfTextAtSize("Action required", size) + 22;
}

// Tinted label with a 3pt full-colour line on the left and deep green text, all the same width.
export function drawStatusLabel({ page, rgb, fonts, x, y, kind, size = 8, h = 16 }) {
  const st = BRAND.status[kind] || BRAND.status.pending;
  const w = statusWidth(fonts, size);
  page.drawRectangle({ x, y, width: w, height: h, color: hexColor(rgb, st.fill) });
  page.drawRectangle({ x, y, width: 3, height: h, color: hexColor(rgb, st.line) });
  page.drawText(st.label, { x: x + 11, y: y + (h - size) / 2 + 1.5, size, font: fonts.label, color: hexColor(rgb, BRAND.deep) });
  return w;
}

// Short label for narrow cells (the weekly tracker's Y, N, P).
export function drawStatusChip({ page, rgb, fonts, x, y, w, h, kind, text, size = 8 }) {
  const st = BRAND.status[kind] || BRAND.status.pending;
  page.drawRectangle({ x, y, width: w, height: h, color: hexColor(rgb, st.fill) });
  page.drawRectangle({ x, y, width: 3, height: h, color: hexColor(rgb, st.line) });
  const tw = fonts.label.widthOfTextAtSize(text, size);
  page.drawText(text, { x: x + 3 + (w - 3 - tw) / 2, y: y + (h - size) / 2 + 1.5, size, font: fonts.label, color: hexColor(rgb, BRAND.deep) });
}
